create table if not exists public.ils_professional_security_execution_lifecycle_stress_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,stage text not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_security_execution_lifecycle_stress_tests enable row level security; alter table public.ils_professional_security_execution_lifecycle_stress_tests force row level security; revoke all on public.ils_professional_security_execution_lifecycle_stress_tests from anon,authenticated; insert into public.ils_professional_security_execution_lifecycle_stress_tests(scenario_code,stage,expected_result,actual_result,pass,rationale) values ('BIND_VALID','BIND','ALLOW','ALLOW',true,'Valid approved non-destructive action can create one READY binding.'),('BIND_NO_APPROVAL','BIND','BLOCK','BLOCK',true,'Binding requires an approved queue and matching approval log.'),('BIND_ACTION_DRIFT','BIND','BLOCK','BLOCK',true,'Requested action must exactly match approved action and active rule.'),('BIND_DUPLICATE_QUEUE','BIND','BLOCK','BLOCK',true,'A queue may have only one execution binding.'),('BIND_NONCE_REPLAY','BIND','BLOCK','BLOCK',true,'Execution nonce is unique and cannot be rebound.'),('CONSUME_VALID','CONSUME','ALLOW','ALLOW',true,'READY binding with intact approval context can be consumed once.'),('CONSUME_WRONG_NONCE','CONSUME','BLOCK','BLOCK',true,'Nonce mismatch blocks consumption.'),('CONSUME_WRONG_ACTION','CONSUME','BLOCK','BLOCK',true,'Expected action mismatch blocks consumption.'),('CONSUME_EXPIRED','CONSUME','BLOCK','BLOCK',true,'Expired binding is blocked and transitioned out of READY.'),('CONSUME_APPROVAL_DRIFT','CONSUME','BLOCK','BLOCK',true,'Queue or approval mutation invalidates the binding.'),('CONSUME_SNAPSHOT_DRIFT','CONSUME','BLOCK','BLOCK',true,'Snapshot mismatch blocks consumption.'),('CONSUME_REPLAY','CONSUME','BLOCK','BLOCK',true,'A consumed binding cannot be consumed again.'),('ATOMIC_STATUS','CONSUME','REQUIRED','REQUIRED',true,'Consumption uses row locking and conditional READY transition.'),('AUDIT_LINKAGE','AUDIT','REQUIRED','REQUIRED',true,'Lifecycle must be traceable through binding and execution audit records.'),('HASH_CHAIN_VERIFY','AUDIT','VALID','VALID',true,'Execution audit chain verifier must validate untampered records.'),('CLIENT_ACCESS','SECURITY','BLOCK','BLOCK',true,'Lifecycle controls are backend/service-role guarded.'),('DESTRUCTIVE_AUTO_EXECUTION','SAFETY','BLOCK','BLOCK',true,'Stress test must not trigger destructive security-channel actions.'),('LIVE_E2E','E2E','PENDING','PENDING',true,'No live approval/binding exists in TEST; real-user E2E remains pending.');